import type { Question } from '../../../../src/types/course'

const verifiedAt = '2026-09-13'

type QConfig = {
  id: string
  moduleId: string
  skillIds: string[]
  type: 'pjs' | 'single'
  difficulty: 1 | 2 | 3 | 4 | 5
  stem: string
  case?: string
  options: [string, string][]
  correct: 0 | 1 | 2
  explanation: string
  sourceIds: string[]
}

function q(config: QConfig): Question {
  const ids = ['a', 'b', 'c'] as const
  const rotation = Array.from(config.id).reduce((sum, char) => sum + char.charCodeAt(0), 0) % 3
  const indexed = config.options.map((option, index) => ({ option, isCorrect: index === config.correct }))
  const rotated = [...indexed.slice(rotation), ...indexed.slice(0, rotation)]
  const correctIndex = rotated.findIndex(({ isCorrect }) => isCorrect)

  const options = rotated.map(({ option: [text, rationale] }, index) => {
    const id = ids[index]
    if (!id) throw new Error(`Índice de opción inválido en ${config.id}: ${index}`)
    return { id, text, rationale }
  })
  const correctOptionId = ids[correctIndex]
  if (!correctOptionId) throw new Error(`No fue posible resolver la opción correcta de ${config.id}`)

  return {
    id: config.id,
    moduleId: config.moduleId,
    skillIds: config.skillIds,
    type: config.type,
    difficulty: config.difficulty,
    stem: config.stem,
    ...(config.case !== undefined ? { case: config.case } : {}),
    options,
    correctOptionId,
    explanation: config.explanation,
    sourceIds: config.sourceIds,
    verifiedAt,
  }
}

